import 'package:flutter/material.dart';

class Penghitung extends StatefulWidget {
  const Penghitung({super.key});

  @override
  State<Penghitung> createState() => _PenghitungState();
}

class _PenghitungState extends State<Penghitung> {
  int jumlah = 0; // data yang berubah disimpan di State

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Keranjang')),
      body: Center(
        child: Text('$jumlah barang', style: const TextStyle(fontSize: 24)),
      ),
      floatingActionButton: FloatingActionButton(
        // setState mengubah data lalu meminta build dipanggil ulang
        onPressed: () => setState(() => jumlah++),
        child: const Icon(Icons.add),
      ),
    );
  }
}

void main() => runApp(const MaterialApp(home: Penghitung()));

