sealed class StokEvent {}
class BarangMasuk extends StokEvent {
  final int jumlah;
  BarangMasuk(this.jumlah);
}
class BarangKeluar extends StokEvent {
  final int jumlah;
  BarangKeluar(this.jumlah);
}

class StokBloc extends Bloc<StokEvent, int> {
  StokBloc() : super(0) {
    on<BarangMasuk>((e, emit) => emit(state + e.jumlah));
    on<BarangKeluar>((e, emit) {
      if (e.jumlah <= state) emit(state - e.jumlah); // stok tidak boleh minus
    });
  }
}

