  @override
  State<JadwalSholat> createState() => _JadwalSholatState();
}

class _JadwalSholatState extends State<JadwalSholat> {
  late Future<Map<String, dynamic>> _jadwal;

  @override
  void initState() {
    super.initState();
    _jadwal = ambilJadwal('bandung');
  }

  Future<Map<String, dynamic>> ambilJadwal(String kota) async {
    final res = await http.get(Uri.parse('https://api.contoh.id/sholat/$kota'));
    if (res.statusCode != 200) throw Exception('Server menjawab ${res.statusCode}');
    return jsonDecode(res.body) as Map<String, dynamic>;
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Map<String, dynamic>>(
      future: _jadwal,
      builder: (context, snap) {
        if (snap.connectionState == ConnectionState.waiting) {
          return const Center(child: CircularProgressIndicator());
        }
        if (snap.hasError) {
          return TextButton(
            onPressed: () => setState(() => _jadwal = ambilJadwal('bandung')),
            child: const Text('Gagal memuat. Coba lagi'),
          );
        }
        final j = snap.data!;
        return Text('Subuh ${j['subuh']}  Maghrib ${j['maghrib']}');
      },
    );
  }
}

final dio = Dio(BaseOptions(
  baseUrl: 'https://api.tokokopi.id/v1',
  connectTimeout: const Duration(seconds: 10),
));

Future<List<String>> cariProduk(String kata) async {
  try {
    final res = await dio.get('/produk', queryParameters: {'q': kata, 'batas': 20});
    final daftar = res.data['data'] as List;
    return [for (final p in daftar) p['nama'] as String];
  } on DioException catch (e) {
    if (e.type == DioExceptionType.connectionTimeout) {
      throw Exception('Koneksi lambat, coba lagi');
    }
    throw Exception('Gagal mencari: ${e.response?.statusCode}');
  }
}

